#if canImport(FoundationEssentials)
import FoundationEssentials
#else
import Foundation
#endif

extension VNCProtocol.ARDAuthentication {
	struct DiffieHellmanKeyAgreement {
		struct ValidatedSafePrimeCache {
			let capacity: Int
			private var insertionOrder = [Data]()
			private var values = Set<Data>()

			init(capacity: Int) {
				precondition(capacity > 0)
				self.capacity = capacity
			}

			var count: Int {
				values.count
			}

			func contains(_ value: Data) -> Bool {
				values.contains(value)
			}

			mutating func insert(_ value: Data) {
				guard values.insert(value).inserted else { return }

				insertionOrder.append(value)
				if values.count > capacity {
					values.remove(insertionOrder.removeFirst())
				}
			}
		}

		let publicKey: Data
		let privateKey: Data
		let secretKey: Data

		static func leftPadded(_ value: Data, to length: Int) -> Data? {
			guard length > 0, value.count <= length else { return nil }
			return Data(repeating: 0, count: length - value.count) + value
		}

		init?(prime: Data,
			  generator: Data,
			  peerKey: Data,
			  keyLength: Int) {
			guard Self.validParameters(prime: prime,
									   generator: generator,
									   peerKey: peerKey,
									   keyLength: keyLength) else {
				return nil
			}

			guard let keyPair = Self.generateKeyPair(generator: generator,
													 prime: prime,
													 keyLength: keyLength),
				  !keyPair.privateKey.isEmpty,
				  !keyPair.publicKey.isEmpty else {
				return nil
			}

			guard let secretKey = Self.computeSharedKey(prime: prime,
												peerKey: peerKey,
												privateKey: keyPair.privateKey,
												keyLength: keyLength),
				  !secretKey.isEmpty else {
				return nil
			}

			self.publicKey = keyPair.publicKey
			self.privateKey = keyPair.privateKey
			self.secretKey = secretKey
		}
	}
}

/// One Apple Remote Desktop security-type challenge generated by an RFB host.
/// The challenge is single-use because it contains an ephemeral exponent.
public struct VNCARDHostAuthentication: Sendable {
	public static let responseLength = 256

	public let challenge: Data

	private static let keyLength = 128
	private static let generator = Data([0, 2])
	private static let safePrime = Data([
		0xC6, 0x92, 0xB0, 0x34, 0x3A, 0x9F, 0xC7, 0x7A, 0xB5, 0x4D, 0xD8, 0xF0, 0x91, 0x2F,
		0x24, 0xE6, 0x57, 0xBA, 0xCB, 0x3D, 0x42, 0x72, 0xE6, 0x52, 0x5E, 0x62, 0x4D, 0xCB,
		0xAB, 0x26, 0xA4, 0x79, 0x90, 0x41, 0x18, 0x11, 0x1C, 0xCE, 0x78, 0x2B, 0x67, 0x09,
		0x52, 0x2B, 0xD2, 0x01, 0xF1, 0x5C, 0x38, 0xED, 0xF1, 0xB3, 0xE9, 0x4D, 0xEA, 0xA7,
		0xDE, 0xE9, 0x1B, 0x4B, 0x46, 0x19, 0x60, 0x7B, 0x3B, 0x76, 0xE1, 0xA1, 0xF9, 0xB6,
		0x5F, 0x6F, 0x54, 0x5D, 0x42, 0x98, 0x2F, 0xEE, 0x07, 0xF1, 0xF7, 0x8D, 0x58, 0x55,
		0xE9, 0xC4, 0x90, 0xCA, 0xD9, 0xB4, 0x58, 0x55, 0xF6, 0xBD, 0xEA, 0x75, 0xBF, 0x54,
		0x96, 0x43, 0xA5, 0x72, 0x57, 0x1B, 0x9F, 0x80, 0x73, 0xEE, 0x56, 0xA3, 0x6D, 0xD1,
		0xB9, 0xEA, 0xD5, 0x0D, 0xCF, 0x44, 0x44, 0x06, 0xBF, 0xDF, 0xD8, 0x51, 0xDE, 0x76,
		0xE5, 0x1B,
	])

	private let ephemeralExponent: Data

	public init() throws {
		typealias Agreement = VNCProtocol.ARDAuthentication.DiffieHellmanKeyAgreement
		guard
			Agreement.validParameters(
				prime: Self.safePrime,
				generator: Self.generator,
				peerKey: Self.paddedValue(2),
				keyLength: Self.keyLength),
			let keyPair = Agreement.generateKeyPair(
				generator: Self.generator,
				prime: Self.safePrime,
				keyLength: Self.keyLength)
		else {
			throw VNCARDHostAuthenticationError.keyGenerationFailed
		}

		ephemeralExponent = keyPair.privateKey
		var wire = Data(Self.generator)
		var keyLength = UInt16(Self.keyLength).bigEndian
		withUnsafeBytes(of: &keyLength) { wire.append(contentsOf: $0) }
		wire.append(Self.safePrime)
		wire.append(keyPair.publicKey)
		challenge = wire
	}

	public func verifies(response: Data, password: String) -> Bool {
		guard response.count == Self.responseLength else { return false }
		let cipherText = response.prefix(128)
		let peerKey = response.suffix(Self.keyLength)
		typealias Agreement = VNCProtocol.ARDAuthentication.DiffieHellmanKeyAgreement
		guard
			Agreement.validParameters(
				prime: Self.safePrime,
				generator: Self.generator,
				peerKey: Data(peerKey),
				keyLength: Self.keyLength),
			let sharedKey = Self.deriveSharedKey(
				peerKey: Data(peerKey),
				exponent: ephemeralExponent),
			let clearText = AES128ECBEncryption.decrypt(
				data: Data(cipherText),
				key: sharedKey.md5Hash()),
			clearText.count == 128,
			let passwordEnd = clearText[64..<128].firstIndex(of: 0)
		else { return false }

		let receivedCredential = clearText[64..<passwordEnd]
		let expectedCredential = VNCProtocol.ARDAuthentication.Authentication.credentialBytes(
			for: password)
		return Self.constantTimeEqual(Data(receivedCredential), expectedCredential)
	}

	private static func deriveSharedKey(peerKey: Data, exponent: Data) -> Data? {
		guard let prime = BigNum(data: safePrime),
			let peer = BigNum(data: peerKey),
			let exponent = BigNum(data: exponent)
		else { return nil }
		let shared = BigNum()
		guard BigNum.modExp(y: shared, g: peer, x: exponent, p: prime),
			!shared.isZero,
			let minimal = shared.bigEndianData()
		else { return nil }
		return VNCProtocol.ARDAuthentication.DiffieHellmanKeyAgreement.leftPadded(
			minimal,
			to: keyLength)
	}

	private static func paddedValue(_ value: UInt8) -> Data {
		Data(repeating: 0, count: keyLength - 1) + Data([value])
	}

	private static func constantTimeEqual(_ lhs: Data, _ rhs: Data) -> Bool {
		var difference = UInt8(truncatingIfNeeded: lhs.count ^ rhs.count)
		let count = max(lhs.count, rhs.count)
		for index in 0..<count {
			let left = index < lhs.count ? lhs[index] : 0
			let right = index < rhs.count ? rhs[index] : 0
			difference |= left ^ right
		}
		return difference == 0
	}
}

public enum VNCARDHostAuthenticationError: Error {
	case keyGenerationFailed
}

private extension VNCProtocol.ARDAuthentication.DiffieHellmanKeyAgreement {
	static let safePrimeCondition = NSCondition()
	static var validatedSafePrimes = ValidatedSafePrimeCache(capacity: 32)
	static var rejectedSafePrimes = Set<Data>()
	static var safePrimeValidations = Set<Data>()

	struct KeyPair {
		let publicKey: Data
		let privateKey: Data
	}

	static func validParameters(prime: Data,
								generator: Data,
								peerKey: Data,
								keyLength: Int) -> Bool {
		guard keyLength >= 128,
			  keyLength <= 512,
			  prime.count == keyLength,
			  peerKey.count == keyLength,
			  let bigPrime = BigNum(data: prime),
			  bigPrime.bitsCount == keyLength * 8,
			  let bigGenerator = BigNum(data: generator),
			  bigGenerator.isValidDiffieHellmanElement(modulus: bigPrime),
			  let bigPeerKey = BigNum(data: peerKey),
			  bigPeerKey.isValidDiffieHellmanElement(modulus: bigPrime),
			  Self.isSafePrime(prime) else {
			return false
		}

		return true
	}

	static func isSafePrime(_ data: Data) -> Bool {
		safePrimeCondition.lock()
		while safePrimeValidations.contains(data) {
			safePrimeCondition.wait()
		}
		if validatedSafePrimes.contains(data) {
			safePrimeCondition.unlock()
			return true
		}
		if rejectedSafePrimes.contains(data) {
			safePrimeCondition.unlock()
			return false
		}
		safePrimeValidations.insert(data)
		safePrimeCondition.unlock()

		let prime = BigNum(data: data)
		let valid = prime?.isProbablePrime(rounds: 16) == true
			&& prime?.halvedPredecessor?.isProbablePrime(rounds: 16) == true

		safePrimeCondition.lock()
		safePrimeValidations.remove(data)
		if valid {
			validatedSafePrimes.insert(data)
		} else {
			if rejectedSafePrimes.count >= 32, let evicted = rejectedSafePrimes.first {
				rejectedSafePrimes.remove(evicted)
			}
			rejectedSafePrimes.insert(data)
		}
		safePrimeCondition.broadcast()
		safePrimeCondition.unlock()
		return valid
	}

	static func generateKeyPair(generator: Data,
								prime: Data,
								keyLength: Int) -> KeyPair? {
		let bigPrivKey = BigNum()
		let bigPubKey = BigNum()

		guard let bigPrime = BigNum(data: prime),
			  bigPrime.isGreaterThanOne,
			  let bigGenerator = BigNum(data: generator) else {
			return nil
		}

		// Generate DH private key
		repeat {
			let randSuccess = bigPrivKey.rand(range: bigPrime)

			guard randSuccess else {
				return nil
			}
		} while bigPrivKey.isZero

		let modSuccess = BigNum.modExp(y: bigPubKey,
									   g: bigGenerator,
									   x: bigPrivKey,
									   p: bigPrime)

		guard modSuccess, !bigPubKey.isZero else {
			return nil
		}

		guard bigPrivKey.bytesCount <= keyLength,
			  bigPubKey.bytesCount <= keyLength else {
			return nil
		}

		guard let privKey = bigPrivKey.bigEndianData(),
			  let minimalPubKey = bigPubKey.bigEndianData(),
			  let pubKey = leftPadded(minimalPubKey, to: keyLength) else {
			return nil
		}

		let keyPair = KeyPair(publicKey: pubKey,
							  privateKey: privKey)

		return keyPair
	}

	static func computeSharedKey(prime: Data,
								 peerKey: Data,
								 privateKey: Data,
								 keyLength: Int) -> Data? {
		guard let bigPrime = BigNum(data: prime),
			  let bigPrivKey = BigNum(data: privateKey),
			  let bigPeerKey = BigNum(data: peerKey) else {
			return nil
		}

		let bigSharedKey = BigNum()

		let modSuccess = BigNum.modExp(y: bigSharedKey,
									   g: bigPeerKey,
									   x: bigPrivKey,
									   p: bigPrime)

		guard modSuccess, !bigSharedKey.isZero else {
			return nil
		}

		guard let minimalSharedKey = bigSharedKey.bigEndianData(),
			  let sharedKey = leftPadded(minimalSharedKey, to: keyLength) else {
			return nil
		}

		return sharedKey
	}
}
